PROGRAM ST_S02_SORTERING
VAR
    stegPsh1 : INT := 0;
    stegPsh2 : INT := 0;
    stegPsh3 : INT := 0;
    tmr1     : TON;
    tmr2     : TON;
    tmr3     : TON;
    trigDest : R_TRIG;
END_VAR

trigDest(CLK := (ST200_SCN_DEST > 0));

tmr1(IN := (stegPsh1 = 1), PT := T#400ms);
tmr2(IN := (stegPsh2 = 1), PT := T#400ms);
tmr3(IN := (stegPsh3 = 1), PT := T#400ms);

IF NOT EMG_OK OR NOT ST200_PSH_HOME THEN
    ST200_CNV_RUN   := FALSE;
    ST200_PSH1_OUT  := FALSE;
    ST200_PSH2_OUT  := FALSE;
    ST200_PSH3_OUT  := FALSE;
    stegPsh1 := 0;
    stegPsh2 := 0;
    stegPsh3 := 0;
ELSE
    ST200_CNV_RUN := TRUE;

    IF trigDest.Q THEN
        IF ST200_SCN_DEST = 1 THEN
            ST200_PSH1_OUT := TRUE;
            ST200_PSH2_OUT := TRUE;
        END_IF;
    END_IF;

    IF tmr1.Q THEN
        ST200_PSH1_OUT := FALSE;
        stegPsh1 := 0;
    END_IF;
END_IF;
END_PROGRAM
